package io.github.jackotom.hongguo.android;
import java.util.*;import java.util.concurrent.*;import java.net.*;import org.json.*;
interface IBinder{}class Binder implements IBinder{}
class Intent{final String action;Intent(String action){this.action=action;}String getAction(){return action;}}
class CastHandler{final List<Runnable> posted=new ArrayList<>();boolean queued;void post(Runnable action){if(queued)posted.add(action);else action.run();}void flush(){List<Runnable> work=new ArrayList<>(posted);posted.clear();for(Runnable task:work)task.run();}}
class CastLifecycle{boolean closed;List<Runnable> shutdownNow(){closed=true;return Collections.emptyList();}}
class CastServiceBase{static final int START_NOT_STICKY=2,STOP_FOREGROUND_REMOVE=1;int stopCalls,stopId=-1,foregroundStops;boolean baseDestroyed;public IBinder onBind(Intent intent){return null;}public int onStartCommand(Intent intent,int flags,int startId){return 0;}void stopSelf(){stopCalls++;}void stopSelf(int id){stopCalls++;stopId=id;}void stopForeground(int flags){foregroundStops++;}public void onDestroy(){baseDestroyed=true;}}
final class DlnaServiceLifecycleTest{
 static int checks;static void check(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
 static DlnaSession.Snapshot opening(){return DlnaSession.Snapshot.opening("123456","测试剧","合成电视",0,"1080p",true);}
 static JSONObject series()throws Exception{return new JSONObject().put("seriesId","123456").put("title","测试剧");}
 static JSONArray episodes()throws Exception{return new JSONArray().put(new JSONObject().put("vid","111111").put("index",1)).put(new JSONObject().put("vid","222222").put("index",2));}
 static DlnaDevice device()throws Exception{return new DlnaDevice("uuid:fixture","合成电视","192.168.1.8",new URI("http://192.168.1.8/control"),"urn:schemas-upnp-org:service:AVTransport:1");}
 public static void main(String[] args)throws Exception{
  DlnaServiceHarness h=new DlnaServiceHarness();check(h.onBind(new Intent("bind"))!=null&&h.foregrounds==0,"binding never starts foreground or network");
  check(h.diagnostics().contains("尚未连接"),"unconnected diagnostics reads no device state");int beforeStarts=h.begins,beforeForegrounds=h.foregrounds,beforeSerial=h.serial;h.diagnosticReader=()->"控制命令：Play 已受理\n视频 GET=0 HEAD=1 写出正文=0 字节";check(h.diagnostics().contains("GET=0 HEAD=1"),"actual service diagnostics reads current control and byte-server supplier");check(h.begins==beforeStarts&&h.foregrounds==beforeForegrounds&&h.serial==beforeSerial,"reading diagnostics neither connects nor changes service state");
  h.snapshot=opening();check(h.onStartCommand(new Intent(DlnaServiceHarness.KEEP),0,1)==CastServiceBase.START_NOT_STICKY&&h.foregrounds==1,"valid opening KEEP retains nonsticky foreground");
  h.stopCast();int fg=h.foregrounds;h.onStartCommand(new Intent(DlnaServiceHarness.KEEP),0,9);check(h.foregrounds==fg&&h.stopId==9&&h.foregroundStops>0,"late KEEP after stop cannot orphan a foreground notification");h.onStartCommand(null,0,10);check(h.stopId==10&&h.foregrounds==fg,"null restart intent never restores empty session");
  h.main.queued=true;h.publish(opening());h.stopCast();fg=h.foregrounds;h.main.flush();check(h.foregrounds==fg&&!h.snapshot.active,"queued old active snapshot cannot resurrect stopped foreground");
  List<DlnaSession.Snapshot> observed=new ArrayList<>();DlnaServiceHarness.Listener listener=observed::add;h.addListener(listener);h.removeListener(listener);h.main.flush();check(observed.isEmpty(),"unbind before queued initial listener callback retains no UI");h.addListener(listener);h.main.flush();check(observed.size()==1&&!observed.get(0).active,"late bind observes current inactive state");
  h.main.queued=false;h.connect(device(),series(),episodes(),1,"1080p",false,true,27000,1);check(h.begins==1&&h.lastRequest.current==1&&h.lastRequest.resume==27000&&!h.lastRequest.autoplay,"actual connect validates and captures Activity-free compact request");
  DlnaSessionTest.Fixture cast=new DlnaSessionTest.Fixture();cast.start();h.session=cast.session;h.snapshot=cast.session.snapshot();DlnaSession.Snapshot old=h.snapshot;h.connect(device(),series(),episodes(),99,"1080p",true,true,0,1);check(h.snapshot.active&&h.snapshot.current==old.current&&h.snapshot.error.contains("启动未完成")&&cast.server.live.size()==1,"bad new input preserves existing active cast and its supply");
  h.connect(device(),series(),episodes(),0,"720p",true,true,1000,3);check(h.pending!=null&&!cast.session.snapshot().active,"valid replacement requests explicit prior-session stop");int seen=observed.size(),begins=h.begins;h.accept(h.serial,cast.session.snapshot());check(h.begins==begins+1&&h.snapshot.active&&observed.size()==seen,"pending replacement never broadcasts transient old inactive state");
  DlnaServiceHarness close=new DlnaServiceHarness();DlnaSessionTest.Fixture actual=new DlnaSessionTest.Fixture();actual.start();close.session=actual.session;close.snapshot=actual.session.snapshot();close.connecting=new FutureTask<>(()->null);close.main.queued=true;List<DlnaSession.Snapshot> late=new ArrayList<>();close.addListener(late::add);close.publish(opening());int token=close.serial;close.onDestroy();close.main.flush();close.accept(token,opening());check(close.destroyed&&close.baseDestroyed&&close.lifecycle.closed&&close.connecting.isCancelled(),"actual destroy cancels initialization and closes lifecycle executor");check(actual.server.closed&&!actual.session.snapshot().active&&actual.source.media.get(0).references==0,"actual destroy closes session and all supply leases without Activity");check(close.listeners.isEmpty()&&late.isEmpty()&&!close.snapshot.active,"destroy clears bound UI callbacks and rejects old session callbacks");check(close.releases==1&&close.foregroundStops==1,"destroy releases cast locks and removes foreground");
  System.out.println("DLNA_SERVICE_LIFECYCLE_OK checks="+checks+" lifecycleMethods=actualProduction queueValidation=actualProduction lateKeep=handled staleUiCallbacks=ignored bindDoesNotStart=true networkRequests=0 deviceTests=not_run");
 }
}
